package generated;

import com.openjiuwen.core.foundation.tool.Tool;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class WealthQueryTool extends Tool {

  private static final String BALANCE_OPERATION = "get_account_balance";
  private static final String PRODUCTS_OPERATION = "list_wealth_products";
  private static final String INPUT_CONTRACT_ERROR = "TOOL_INPUT_CONTRACT_INVALID";
  private static final String RESPONSE_CONTRACT_ERROR = "TOOL_RESPONSE_CONTRACT_INVALID";

  private final Tool transport;

  public WealthQueryTool(Tool transport) {
    super(transport.getCard());
    this.transport = transport;
  }

  @Override
  protected Object invokeInternal(Map<String, Object> inputs, Map<String, Object> kwargs) throws Exception {
    String operation = transport.getCard().getName();
    if (BALANCE_OPERATION.equals(operation)) {
      requireBalanceInput(inputs);
      return requireBalanceResponse(transport.invoke(inputs, kwargs));
    }
    if (PRODUCTS_OPERATION.equals(operation)) {
      requireProductsInput(inputs);
      return requireProductsResponse(transport.invoke(inputs, kwargs));
    }
    throw new IllegalArgumentException(INPUT_CONTRACT_ERROR);
  }

  private static void requireBalanceInput(Map<String, Object> inputs) {
    if (inputs == null || inputs.size() != 1) {
      throw new IllegalArgumentException(INPUT_CONTRACT_ERROR);
    }
    Object accountId = inputs.get("accountId");
    if (!(accountId instanceof String value) || value.trim().isEmpty()) {
      throw new IllegalArgumentException(INPUT_CONTRACT_ERROR);
    }
  }

  private static void requireProductsInput(Map<String, Object> inputs) {
    if (inputs == null || !inputs.isEmpty()) {
      throw new IllegalArgumentException(INPUT_CONTRACT_ERROR);
    }
  }

  private static Map<String, Object> requireBalanceResponse(Object response) {
    if (!(response instanceof Map<?, ?> source) || source.size() != 4) {
      throw new IllegalStateException(RESPONSE_CONTRACT_ERROR);
    }
    Object accountId = source.get("accountId");
    Object currency = source.get("currency");
    Object availableBalanceFen = source.get("availableBalanceFen");
    Object asOf = source.get("asOf");
    if (!(accountId instanceof String)
        || !(currency instanceof String)
        || !(availableBalanceFen instanceof Integer || availableBalanceFen instanceof Long)
        || !(asOf instanceof String)) {
      throw new IllegalStateException(RESPONSE_CONTRACT_ERROR);
    }
    Map<String, Object> result = new LinkedHashMap<>();
    result.put("accountId", accountId);
    result.put("currency", currency);
    result.put("availableBalanceFen", availableBalanceFen);
    result.put("asOf", asOf);
    return result;
  }

  private static Map<String, Object> requireProductsResponse(Object response) {
    if (!(response instanceof Map<?, ?> source) || source.size() != 2) {
      throw new IllegalStateException(RESPONSE_CONTRACT_ERROR);
    }
    Object items = source.get("items");
    Object version = source.get("version");
    if (!(items instanceof List<?> entries) || !(version instanceof String)) {
      throw new IllegalStateException(RESPONSE_CONTRACT_ERROR);
    }
    List<Object> verifiedItems = new ArrayList<>();
    for (Object entry : entries) {
      if (!(entry instanceof Map<?, ?> item) || item.size() != 5) {
        throw new IllegalStateException(RESPONSE_CONTRACT_ERROR);
      }
      Object productId = item.get("productId");
      Object name = item.get("name");
      Object status = item.get("status");
      Object minimumAmountFen = item.get("minimumAmountFen");
      Object description = item.get("description");
      if (!(productId instanceof String)
          || !(name instanceof String)
          || !(status instanceof String)
          || !(minimumAmountFen instanceof Integer || minimumAmountFen instanceof Long)
          || !(description instanceof String)) {
        throw new IllegalStateException(RESPONSE_CONTRACT_ERROR);
      }
      Map<String, Object> verifiedItem = new LinkedHashMap<>();
      verifiedItem.put("productId", productId);
      verifiedItem.put("name", name);
      verifiedItem.put("status", status);
      verifiedItem.put("minimumAmountFen", minimumAmountFen);
      verifiedItem.put("description", description);
      verifiedItems.add(verifiedItem);
    }
    Map<String, Object> result = new LinkedHashMap<>();
    result.put("items", verifiedItems);
    result.put("version", version);
    return result;
  }
}
